#!/bin/bash
#
# Local Experiment driver against the docker-compose stack generated by
# generate-compose.sh. Structurally mirrors cloudlab/experiment.sh: phased
# ramp per algorithm (all levels of one algorithm back-to-back, then a
# break, then the other algorithm), same summary.tsv/windows.csv format,
# same -a/-m/-p flags.
#
# Phased ramp: with the constant antagonist, running each algorithm across
# all 9 levels back-to-back (no inter-level gap) exposes both algorithms
# to the same steady-state fleet load. A single break separates the two
# algorithm phases.
#
# Usage: ./experiment-local.sh [OPTIONS]
#   -d, --duration SEC        per-level duration (default 60)
#   -g, --gap SEC             break between algorithm phases and cool-down
#                             before calibration (default 15)
#   -b, --baseline QPS        skip auto-calibration
#   -c, --concurrency N       hey workers per phase (default 1000)
#   -t, --timeout SEC         per-request timeout (default 20 — matches
#                             hey default; -t 5 truncates PreQual's tail
#                             which is exactly the signal we want to see)
#   -a, --algo ALGO           both (default) | prequal | rr
#   -m, --metrics 0|1         when given, restart LB containers with
#                             LB_METRICS set to this value before the sweep
#   -p, --picklog 0|1         when given, restart LB containers with
#                             LB_PICK_LOG set to this value before the sweep
#   -P, --probemode MODE      per_query (paper default) or ticker (giacbusc
#                             style: one goroutine ticks every backend).
#                             Restarts LBs.
#   -I, --probeinterval MS    probe tick interval in ms (ticker mode only,
#                             default 1000). Restarts LBs.
#   -o, --out DIR             output dir (default results/experiment-local/<ts>)
#   -h, --help                this message

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

DURATION=60
GAP=15
BASELINE=""
CONC=1000
TIMEOUT=20
ALGO="both"
LB_METRICS_OPT=""
LB_PICK_LOG_OPT=""
LB_PROBE_MODE_OPT=""
LB_PROBE_INTERVAL_MS_OPT=""
OUT_DIR=""

while [[ $# -gt 0 ]]; do
    case $1 in
        -d|--duration)      DURATION="$2"; shift 2 ;;
        -g|--gap)           GAP="$2";      shift 2 ;;
        -b|--baseline)      BASELINE="$2"; shift 2 ;;
        -c|--concurrency)   CONC="$2";     shift 2 ;;
        -t|--timeout)       TIMEOUT="$2";  shift 2 ;;
        -a|--algo)          ALGO="$2";     shift 2 ;;
        -m|--metrics)       LB_METRICS_OPT="$2"; shift 2 ;;
        -p|--picklog)       LB_PICK_LOG_OPT="$2"; shift 2 ;;
        -P|--probemode)     LB_PROBE_MODE_OPT="$2"; shift 2 ;;
        -I|--probeinterval) LB_PROBE_INTERVAL_MS_OPT="$2"; shift 2 ;;
        -o|--out)           OUT_DIR="$2";  shift 2 ;;
        -h|--help)          sed -n '2,/^$/p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *) echo "Unknown option: $1"; exit 1 ;;
    esac
done

case "$LB_PROBE_MODE_OPT" in
    ""|per_query|ticker) ;;
    *) echo "Invalid -P: '$LB_PROBE_MODE_OPT' (must be per_query or ticker)" >&2; exit 1 ;;
esac

case "$ALGO" in
    both|prequal|rr) ;;
    *) echo "Invalid -a: '$ALGO' (must be: both, prequal, rr)" >&2; exit 1 ;;
esac

if ! command -v hey >/dev/null 2>&1; then
    echo "Error: hey is not installed (go install github.com/rakyll/hey@latest)"
    exit 1
fi
if ! command -v docker >/dev/null 2>&1; then
    echo "Error: docker not found"; exit 1
fi

# --- If any -m/-p/-P/-I was given, recreate LB containers with new env ---
if [ -n "$LB_METRICS_OPT" ] || [ -n "$LB_PICK_LOG_OPT" ] || \
   [ -n "$LB_PROBE_MODE_OPT" ] || [ -n "$LB_PROBE_INTERVAL_MS_OPT" ]; then
    if [ -n "$LB_METRICS_OPT" ]; then
        export LB_METRICS="$LB_METRICS_OPT"
    fi
    if [ -n "$LB_PICK_LOG_OPT" ]; then
        export LB_PICK_LOG="$LB_PICK_LOG_OPT"
    fi
    if [ -n "$LB_PROBE_MODE_OPT" ]; then
        export LB_PROBE_MODE="$LB_PROBE_MODE_OPT"
    fi
    if [ -n "$LB_PROBE_INTERVAL_MS_OPT" ]; then
        export LB_PROBE_INTERVAL_MS="$LB_PROBE_INTERVAL_MS_OPT"
    fi
    echo "Restarting LB containers with LB_METRICS=${LB_METRICS_OPT:-<unchanged>} LB_PICK_LOG=${LB_PICK_LOG_OPT:-<unchanged>} LB_PROBE_MODE=${LB_PROBE_MODE_OPT:-<unchanged>} LB_PROBE_INTERVAL_MS=${LB_PROBE_INTERVAL_MS_OPT:-<unchanged>}..."
    # --no-deps avoids recreating the backend/server containers.
    docker-compose up -d --no-deps lb-prequal-1 lb-rr-1
    echo "Sleeping 3s to let LBs settle..."
    sleep 3
fi

# --- Discover running LB containers (no mapfile: macOS bash 3.2 compat) ---
PREQUAL_NAMES=( $(docker ps --format '{{.Names}}' | grep -E '^lb-prequal-[0-9]+$' | sort -V) )
RR_NAMES=(      $(docker ps --format '{{.Names}}' | grep -E '^lb-rr-[0-9]+$'      | sort -V) )

if [ "${#PREQUAL_NAMES[@]}" -eq 0 ] || [ "${#RR_NAMES[@]}" -eq 0 ]; then
    echo "Error: no running lb-prequal-* or lb-rr-* containers."
    echo "       Run: ./generate-compose.sh --servers 8 --lbs 1 && docker-compose up --build -d"
    exit 1
fi

PREQUAL_NAME="${PREQUAL_NAMES[0]}"
RR_NAME="${RR_NAMES[0]}"

host_port_for() {
    docker port "$1" 8080/tcp 2>/dev/null | awk -F: 'NR==1 {print $NF}'
}

PREQUAL_PORT=$(host_port_for "$PREQUAL_NAME")
RR_PORT=$(host_port_for "$RR_NAME")
[ -z "$PREQUAL_PORT" ] && { echo "Error: cannot find host port for $PREQUAL_NAME"; exit 1; }
[ -z "$RR_PORT" ]      && { echo "Error: cannot find host port for $RR_NAME";      exit 1; }

PREQUAL_URL="http://localhost:$PREQUAL_PORT/"
RR_URL="http://localhost:$RR_PORT/"

n_srv=$(docker ps --format '{{.Names}}' | grep -cE '^server[0-9]+$' || true)

TS=$(date +%Y%m%d-%H%M%S)
[ -z "$OUT_DIR" ] && OUT_DIR="results/experiment-local/$TS"
mkdir -p "$OUT_DIR"
WINDOWS="$OUT_DIR/windows.csv"
SUMMARY="$OUT_DIR/summary.tsv"

echo "=========================================="
echo "  Figure 6 - local (phased ramp)"
echo "  PreQual target: $PREQUAL_URL ($PREQUAL_NAME)"
echo "  RR target:      $RR_URL ($RR_NAME)"
echo "  Backends:       $n_srv"
echo "  Algorithm(s):   $ALGO"
echo "  hey:            c=${CONC} timeout=${TIMEOUT}s"
echo "  Output:         ${OUT_DIR}"
echo "=========================================="

for url in "$PREQUAL_URL" "$RR_URL"; do
    if ! curl -fsS --max-time 5 "$url" -o /dev/null; then
        echo "  Error: not reachable: $url"; exit 1
    fi
done

# --- Calibration: uncapped burst against the RR LB ---
if [ -z "$BASELINE" ]; then
    echo "Warming up backends (15s at c=${CONC} on $RR_URL)..."
    hey -z 15s -c "$CONC" -t "$TIMEOUT" "$RR_URL" > /dev/null 2>&1 || true

    echo "Calibrating baseline (45s uncapped on $RR_URL, c=${CONC})..."
    BASELINE=$(hey -z 45s -c "$CONC" -t "$TIMEOUT" "$RR_URL" \
        2>&1 | awk '/Requests\/sec:/ {printf "%.0f", $2; exit}')
    if [ -z "$BASELINE" ] || [ "$BASELINE" = "0" ]; then
        echo "Calibration failed; supply --baseline manually."; exit 1
    fi
    echo "Cool-down ${GAP}s before phase 1..."
    sleep "$GAP"
fi
echo "Baseline (100%) = ${BASELINE} req/sec per algorithm"

echo "algorithm,level_pct,target_qps,t_start_unix,t_end_unix" > "$WINDOWS"
printf "algorithm\tlevel_pct\ttarget_qps\trps\tp50_ms\tp90_ms\tp99_ms\terror_pct\n" > "$SUMMARY"

LEVELS_PCT=(75  103  127 174)

parse_hey() {
    local f=$1
    local rps p50 p90 p99 errpct nonok errs total
    rps=$(awk '/Requests\/sec:/ {printf "%.2f", $2; exit}' "$f")
    p50=$(awk '/  50%+ in/ {printf "%.3f", $3*1000; exit}' "$f")
    p90=$(awk '/  90%+ in/ {printf "%.3f", $3*1000; exit}' "$f")
    p99=$(awk '/  99%+ in/ {printf "%.3f", $3*1000; exit}' "$f")
    total=$(awk '/Total responses:/ {print $3; exit} /Total:/ {print $2; exit}' "$f")
    nonok=$(awk '
        /Status code distribution:/ {flag=1; next}
        flag && /^$/ {flag=0}
        flag && /\[[0-9]+\]/ {
            code=$2+0; n=$1+0;
            if (code < 200 || code >= 300) sum += n;
        }
        END {print sum+0}' "$f")
    errs=$(awk '
        /Error distribution:/ {flag=1; next}
        flag && /^$/ {flag=0}
        flag && /\[[0-9]+\]/ {sum += $1+0}
        END {print sum+0}' "$f")
    if [ -z "$total" ] || [ "$total" = "0" ] || [ "$total" = "0.0000" ]; then
        errpct="0.000"
    else
        errpct=$(awk -v n="$nonok" -v e="$errs" -v t="$total" 'BEGIN {printf "%.3f", 100*(n+e)/t}')
    fi
    printf "%s\t%s\t%s\t%s\n" "${rps:-0}" "${p50:-0}" "${p90:-0}" "${p99:-0}"
    echo "$errpct"
}

# Ramp one algorithm across all levels, back-to-back, no inter-level gap.
run_ramp() {
    local algo=$1 url=$2 outprefix=$3
    echo
    echo "============ Phase: $algo ramp (no inter-level gap) ============"
    for i in "${!LEVELS_PCT[@]}"; do
        local pct=${LEVELS_PCT[$i]}
        local qps
        qps=$(awk -v b="$BASELINE" -v p="$pct" 'BEGIN {printf "%.0f", b*p/100}')
        local per_worker
        per_worker=$(awk -v q="$qps" -v c="$CONC" 'BEGIN { printf "%.4f", q/c }')

        echo "  $algo level $((i+1))/${#LEVELS_PCT[@]}: ${pct}% (${qps} qps)"
        local t_start t_end
        t_start=$(date +%s)
        hey -z "${DURATION}s" -q "$per_worker" -c "$CONC" -t "$TIMEOUT" \
            "$url" > "$OUT_DIR/${outprefix}_${i}.txt" 2>&1
        t_end=$(date +%s)
        echo "$algo,${pct},${qps},${t_start},${t_end}" >> "$WINDOWS"
    done
}

# --- Phase 1: RR ramp ---
if [ "$ALGO" = "both" ] || [ "$ALGO" = "rr" ]; then
    run_ramp roundrobin "$RR_URL" rr
fi

# --- Break between phases (only if both are being run) ---
if [ "$ALGO" = "both" ]; then
    echo
    echo "============ Break: ${GAP}s ============"
    sleep "$GAP"
fi

# --- Phase 2: PreQual ramp ---
if [ "$ALGO" = "both" ] || [ "$ALGO" = "prequal" ]; then
    run_ramp prequal "$PREQUAL_URL" prequal
fi

# --- Parse everything into summary.tsv and print a comparison table ---
echo
echo "============ Results ============"
for i in "${!LEVELS_PCT[@]}"; do
    pct=${LEVELS_PCT[$i]}
    qps=$(awk -v b="$BASELINE" -v p="$pct" 'BEGIN {printf "%.0f", b*p/100}')
    if [ "$ALGO" = "both" ] || [ "$ALGO" = "prequal" ]; then
        {
            read -r line; read -r ep
            printf "prequal\t%s\t%s\t%s\t%s\n" "$pct" "$qps" "$line" "$ep"
        } < <(parse_hey "$OUT_DIR/prequal_${i}.txt") >> "$SUMMARY"
    fi
    if [ "$ALGO" = "both" ] || [ "$ALGO" = "rr" ]; then
        {
            read -r line; read -r ep
            printf "roundrobin\t%s\t%s\t%s\t%s\n" "$pct" "$qps" "$line" "$ep"
        } < <(parse_hey "$OUT_DIR/rr_${i}.txt") >> "$SUMMARY"
    fi
done
column -t -s $'\t' "$SUMMARY"

echo
echo "=========================================="
echo "  Done. Results in $OUT_DIR"
echo "    windows.csv  -> $WINDOWS"
echo "    summary.tsv  -> $SUMMARY"
echo
echo "Render figure with:"
echo "  python3 cloudlab/plot_experiment.py $OUT_DIR --no-cpu"
echo "=========================================="
